def validate_review(path: Path) -> None:
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        required = {"sequence_id", "frame_index", "filename", "status", "reason", "mask_area", "bbox_x1", "bbox_y1", "bbox_x2", "bbox_y2", "previous_iou", "center_shift", "area_ratio"}
        missing = required - set(reader.fieldnames or [])
        if missing:
            raise ValueError(f"Missing columns in {path}: {sorted(missing)}")
        for row in reader:
            status = row["status"]
            if status not in {"ok", "review", "no_device"}:
                raise ValueError(f"Invalid status {status!r} in {path}")


def main() -> int:
